// Simple Chart.js alternative for Chrome Extension
class SimpleChart {
    constructor(ctx, config) {
        this.ctx = ctx;
        this.config = config;
        this.canvas = ctx.canvas;
        this.width = this.canvas.width;
        this.height = this.canvas.height;
        
        // Set canvas size based on container
        const rect = this.canvas.getBoundingClientRect();
        this.canvas.width = rect.width * window.devicePixelRatio;
        this.canvas.height = rect.height * window.devicePixelRatio;
        this.ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
        
        this.width = rect.width;
        this.height = rect.height;
        
        this.render();
    }
    
    render() {
        const ctx = this.ctx;
        const data = this.config.data;
        const options = this.config.options || {};
        
        // Clear canvas
        ctx.clearRect(0, 0, this.width, this.height);
        
        if (this.config.type === 'line') {
            this.renderLineChart(ctx, data, options);
        } else if (this.config.type === 'bar') {
            this.renderBarChart(ctx, data, options);
        } else if (this.config.type === 'doughnut' || this.config.type === 'pie') {
            this.renderDoughnutChart(ctx, data, options);
        }
    }
    
    renderLineChart(ctx, data, options) {
        const padding = 40;
        const chartWidth = this.width - (padding * 2);
        const chartHeight = this.height - (padding * 2);
        
        // Draw axes
        ctx.strokeStyle = '#e5e7eb';
        ctx.lineWidth = 1;
        
        // Y-axis
        ctx.beginPath();
        ctx.moveTo(padding, padding);
        ctx.lineTo(padding, this.height - padding);
        ctx.stroke();
        
        // X-axis
        ctx.beginPath();
        ctx.moveTo(padding, this.height - padding);
        ctx.lineTo(this.width - padding, this.height - padding);
        ctx.stroke();
        
        // Draw data
        if (data.datasets && data.datasets.length > 0) {
            const dataset = data.datasets[0];
            const points = dataset.data || [];
            const labels = data.labels || [];
            
            if (points.length > 0) {
                const maxValue = Math.max(...points, 1);
                const stepX = chartWidth / Math.max(points.length - 1, 1);
                
                // Fill area if specified
                if (dataset.fill) {
                    ctx.fillStyle = dataset.backgroundColor || 'rgba(59, 130, 246, 0.1)';
                    ctx.beginPath();
                    ctx.moveTo(padding, this.height - padding);
                    
                    points.forEach((point, index) => {
                        const x = padding + (index * stepX);
                        const y = this.height - padding - ((point / maxValue) * chartHeight);
                        ctx.lineTo(x, y);
                    });
                    
                    ctx.lineTo(this.width - padding, this.height - padding);
                    ctx.closePath();
                    ctx.fill();
                }
                
                // Draw line
                ctx.strokeStyle = dataset.borderColor || '#3b82f6';
                ctx.lineWidth = dataset.borderWidth || 2;
                ctx.beginPath();
                
                points.forEach((point, index) => {
                    const x = padding + (index * stepX);
                    const y = this.height - padding - ((point / maxValue) * chartHeight);
                    
                    if (index === 0) {
                        ctx.moveTo(x, y);
                    } else {
                        ctx.lineTo(x, y);
                    }
                });
                ctx.stroke();
                
                // Draw points
                const pointRadius = dataset.pointRadius || 3;
                ctx.fillStyle = dataset.pointBackgroundColor || dataset.borderColor || '#3b82f6';
                
                points.forEach((point, index) => {
                    const x = padding + (index * stepX);
                    const y = this.height - padding - ((point / maxValue) * chartHeight);
                    
                    ctx.beginPath();
                    ctx.arc(x, y, pointRadius, 0, 2 * Math.PI);
                    ctx.fill();
                    
                    // Point border
                    if (dataset.pointBorderWidth > 0) {
                        ctx.strokeStyle = dataset.pointBorderColor || '#fff';
                        ctx.lineWidth = dataset.pointBorderWidth;
                        ctx.stroke();
                    }
                });
                
                // Draw labels
                ctx.fillStyle = '#6b7280';
                ctx.font = '12px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';
                ctx.textAlign = 'center';
                
                labels.forEach((label, index) => {
                    if (index < points.length) {
                        const x = padding + (index * stepX);
                        const y = this.height - padding + 20;
                        ctx.fillText(label, x, y);
                    }
                });
            }
        }
    }
    
    renderBarChart(ctx, data, options) {
        const padding = 40;
        const chartWidth = this.width - (padding * 2);
        const chartHeight = this.height - (padding * 2);
        
        if (data.datasets && data.datasets.length > 0) {
            const dataset = data.datasets[0];
            const points = dataset.data || [];
            const labels = data.labels || [];
            
            if (points.length > 0) {
                const maxValue = Math.max(...points, 1);
                const barWidth = chartWidth / points.length * 0.6;
                const barSpacing = chartWidth / points.length * 0.4;
                
                // Extract colors array if it's an array, otherwise use single color
                const colors = Array.isArray(dataset.backgroundColor) 
                    ? dataset.backgroundColor 
                    : [dataset.backgroundColor || '#3b82f6'];
                
                points.forEach((point, index) => {
                    const x = padding + (index * (barWidth + barSpacing)) + barSpacing/2;
                    const barHeight = (point / maxValue) * chartHeight;
                    const y = this.height - padding - barHeight;
                    
                    ctx.fillStyle = colors[index % colors.length];
                    ctx.fillRect(x, y, barWidth, barHeight);
                });
                
                // Draw labels
                ctx.fillStyle = '#6b7280';
                ctx.font = '12px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';
                ctx.textAlign = 'center';
                
                labels.forEach((label, index) => {
                    if (index < points.length) {
                        const x = padding + (index * (barWidth + barSpacing)) + barSpacing/2 + barWidth/2;
                        const y = this.height - padding + 20;
                        ctx.fillText(label, x, y);
                    }
                });
            }
        }
    }
    
    renderDoughnutChart(ctx, data, options) {
        const centerX = this.width / 2;
        const centerY = this.height / 2;
        const radius = Math.min(this.width, this.height) / 2 - 40;
        const innerRadius = radius * 0.5;
        
        if (data.datasets && data.datasets.length > 0) {
            const dataset = data.datasets[0];
            const points = dataset.data || [];
            const labels = data.labels || [];
            const colors = dataset.backgroundColor || [
                '#3b82f6', '#ef4444', '#10b981', '#f59e0b', 
                '#8b5cf6', '#06b6d4', '#f97316', '#84cc16'
            ];
            
            const total = points.reduce((sum, val) => sum + val, 0);
            if (total === 0) return;
            
            let currentAngle = -Math.PI / 2;
            
            points.forEach((point, index) => {
                const sliceAngle = (point / total) * 2 * Math.PI;
                
                ctx.fillStyle = colors[index % colors.length];
                ctx.beginPath();
                ctx.arc(centerX, centerY, radius, currentAngle, currentAngle + sliceAngle);
                ctx.arc(centerX, centerY, innerRadius, currentAngle + sliceAngle, currentAngle, true);
                ctx.closePath();
                ctx.fill();
                
                currentAngle += sliceAngle;
            });
            
            // Draw legend
            if (labels.length > 0) {
                ctx.font = '12px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';
                const legendX = this.width - 100;
                let legendY = 40;
                
                labels.forEach((label, index) => {
                    if (index < points.length && points[index] > 0) {
                        // Color box
                        ctx.fillStyle = colors[index % colors.length];
                        ctx.fillRect(legendX, legendY, 12, 12);
                        
                        // Label text
                        ctx.fillStyle = '#374151';
                        ctx.fillText(label, legendX + 20, legendY + 10);
                        
                        legendY += 20;
                    }
                });
            }
        }
    }
    
    update() {
        this.render();
    }
    
    destroy() {
        // Cleanup if needed
        this.ctx.clearRect(0, 0, this.width, this.height);
    }
}

// Global Chart object to mimic Chart.js
window.Chart = SimpleChart;
